"""Client for the inventory service."""
from app.policy import make_session


class InventoryClient:
    def __init__(self, base_url, session=None):
        self.base_url = base_url.rstrip("/")
        self.session = session or make_session()

    def _url(self, path):
        return self.base_url + path

    def list_items(self, **filters):
        resp = self.session.get(self._url("/items"), params=filters, timeout=5)
        resp.raise_for_status()
        return resp.json()["items"]

    def create_item(self, item):
        resp = self.session.post(self._url("/items"), json=item, timeout=5)
        return resp.status_code, resp.json()

    def health(self):
        resp = self.session.get(self._url("/health"), timeout=2)
        return resp.status_code

    def export_csv(self):
        resp = self.session.get(self._url("/export.csv"), stream=True, timeout=10)
        resp.raise_for_status()
        return b"".join(resp.iter_content(chunk_size=64)).decode("utf-8")

