"""TLS settings for the legacy partner endpoint, which only speaks a few cipher suites."""
import requests
from requests.adapters import HTTPAdapter
from requests.packages.urllib3.exceptions import SubjectAltNameWarning
from requests.packages.urllib3.util import ssl_


def partner_cipher_string():
    """urllib3's default suites minus the weak ones, the recipe the partner's docs give."""
    return ssl_.DEFAULT_CIPHERS + ":!aNULL:!eNULL:!MD5:!DSS"


class PartnerTLSAdapter(HTTPAdapter):
    def init_poolmanager(self, *args, **kwargs):
        kwargs["ssl_context"] = ssl_.create_urllib3_context(ciphers=partner_cipher_string())
        return super().init_poolmanager(*args, **kwargs)


def quiet_partner_warnings():
    """The partner's certificate has no subjectAltName; silence urllib3's warning about it."""
    requests.packages.urllib3.disable_warnings(SubjectAltNameWarning)
    return True

