"""Offline transport: answers requests from recorded responses (a cassette), for demos and tests."""
import io

from requests.adapters import HTTPAdapter
from urllib3.exceptions import MaxRetryError
from urllib3.response import HTTPResponse


class ReplayPool:
    """Stands in for a urllib3 connection pool: urlopen() replays the recorded responses, and
    retries the way urllib3 does (without sleeping)."""

    def __init__(self, cassette):
        self.cassette = {key: list(answers) for key, answers in cassette.items()}
        self.log = []

    def urlopen(self, method, url, body=None, headers=None, retries=None, **kwargs):
        answers = self.cassette.get((method, url)) or [(404, {}, b"")]
        while True:
            self.log.append((method, url))
            status, resp_headers, payload = answers.pop(0) if len(answers) > 1 else answers[0]
            if retries is not None and retries.is_retry(method, status):
                try:
                    retries = retries.increment(method, url)
                    continue
                except MaxRetryError:
                    if retries.raise_on_status:
                        raise
            return HTTPResponse(body=io.BytesIO(payload), headers=resp_headers, status=status,
                                reason="Replayed", preload_content=False,
                                decode_content=kwargs.get("decode_content", True))


class ReplayAdapter(HTTPAdapter):
    """An HTTPAdapter whose connection pool is the replay pool."""

    def __init__(self, cassette, **kwargs):
        self.pool = ReplayPool(cassette)
        super().__init__(**kwargs)

    def get_connection(self, url, proxies=None):
        return self.pool

