import gzip
import json
import ssl

import pytest

from app import policy, transport
from app.client import InventoryClient

ITEMS = [{"sku": "A-1", "name": "hammer", "kind": "tool"}, {"sku": "B-7", "name": "saw", "kind": "tool"}]
CSV = "sku,name\n" + "".join(f"X-{i},item {i}\n" for i in range(40))


def _json(status, payload):
    return (status, {"Content-Type": "application/json"}, json.dumps(payload).encode())


@pytest.fixture
def cassette():
    return {
        ("GET", "/items?kind=tool"): [_json(200, {"items": ITEMS})],
        ("POST", "/items"): [_json(503, {"error": "busy"}), _json(201, {"sku": "C-3"})],
        ("GET", "/health"): [_json(503, {}), _json(502, {}), _json(200, {"ok": True})],
        ("GET", "/export.csv"): [(200, {"Content-Type": "text/csv", "Content-Encoding": "gzip"},
                                  gzip.compress(CSV.encode(), mtime=0))],
    }


@pytest.fixture
def client(cassette):
    adapter = transport.ReplayAdapter(cassette, max_retries=policy.retry_policy())
    return InventoryClient("http://inventory.test/", session=policy.make_session(adapter=adapter))


def test_retry_policy():
    retry = policy.retry_policy()
    assert retry.total == 3
    assert retry.is_retry("GET", 503) and not retry.is_retry("POST", 503)
    assert policy.worst_case_wait(retry) == 2.0
    assert policy.worst_case_wait(policy.retry_policy(total=12, backoff=1)) == 120


def test_session_defaults():
    session = policy.make_session()
    assert session.headers["User-Agent"] == "inventory-client/1.4"
    assert session.get_adapter("https://x.test").max_retries.total == 3


def test_list_items(client):
    assert [i["sku"] for i in client.list_items(kind="tool")] == ["A-1", "B-7"]


def test_get_is_retried_until_healthy(client):
    assert client.health() == 200
    assert client.session.get_adapter("http://x").pool.log.count(("GET", "/health")) == 3


def test_post_is_not_retried(client):
    assert client.create_item({"name": "drill"}) == (503, {"error": "busy"})


def test_export_is_decompressed(client):
    assert client.export_csv() == CSV


def test_partner_tls():
    from app import tls

    assert tls.quiet_partner_warnings() is True
    assert tls.partner_cipher_string().endswith(":!aNULL:!eNULL:!MD5:!DSS")
    adapter = tls.PartnerTLSAdapter()
    ctx = adapter.poolmanager.connection_pool_kw["ssl_context"]
    assert isinstance(ctx, ssl.SSLContext)
    assert not [c for c in ctx.get_ciphers() if "MD5" in c["name"] or "NULL" in c["name"]]

