def peek(self, path, size=16):
    """The first bytes of a (possibly compressed) body, without downloading all of it."""
    resp = self.session.get(self._url(path), stream=True, timeout=5)
    try:
        return resp.raw.read(size, decode_content=True)
    finally:
        resp.close()

def test_peek_reads_at_most_size(client):
    # A weak test, as real suites often are: it only checks the bound.
    assert len(client.peek("/export.csv", size=16)) <= 16
